import 'server-only';

import type { Prisma } from '@prisma/client';

/**
 * Human-readable document numbers (INV-2025-000913, RCP-2025-004411, ...).
 *
 * These are generated by counting existing rows for the year INSIDE the caller's
 * transaction. That is correct under SQLite (single writer) and under Postgres
 * at SERIALIZABLE isolation, but it is NOT collision-proof under READ COMMITTED
 * with concurrent writers — two transactions can read the same count.
 *
 * The safety net is the UNIQUE constraint on each number column: a collision
 * becomes a P2002 error the caller can retry, never a duplicate document. For
 * high write volume, replace the count with a dedicated sequence table or a
 * Postgres SEQUENCE; the interface here stays the same.
 */

export async function nextInvoiceNumber(
  tx: Prisma.TransactionClient,
  year = new Date().getFullYear(),
): Promise<string> {
  const count = await tx.invoice.count({
    where: { invoiceNo: { startsWith: `INV-${year}-` } },
  });
  return `INV-${year}-${String(count + 1).padStart(6, '0')}`;
}

