export async function nextApplicationReference(
  tx: Prisma.TransactionClient,
  year = new Date().getFullYear(),
): Promise<string> {
  const count = await tx.application.count({
    where: { referenceNo: { startsWith: `APP-${year}-` } },
  });
  return `APP-${year}-${String(count + 1).padStart(6, '0')}`;
}

export async function nextMatricSequence(
  tx: Prisma.TransactionClient,
  departmentCode: string,
  year: number,
): Promise<number> {
  const count = await tx.student.count({
    where: { matricNumber: { contains: `/${departmentCode.toUpperCase()}/${year}/` } },
  });
  return count + 1;
}
